record.field:
remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(remote.connection_params or '{}')
except Exception:
    cfg = {}
username = (cfg.get('username') or '').strip()
password = (cfg.get('password') or '').strip()
if not username or not password:
    raise Exception("Missing hidroconta credentials: set username/password in connection_params.")
url = (base_url or '').rstrip('/') + '/Demeter2/v2/login'
resp = request_retry('POST', url, json={'username': username, 'password': password})
if resp.status_code >= 400:
    raise Exception("Login failed: %s %s" % (resp.status_code, resp.text))
jsessionid = resp.cookies.get('JSESSIONID')
if not jsessionid:
    raise Exception("Login OK but no JSESSIONID cookie in response.")
bag['jsessionid'] = jsessionid
result = 'Login OK, JSESSIONID stored in bag'

if 'jsessionid' not in bag:
    raise Exception('Please run "Hidroconta: Login" action first')
Remote = self.remote_id
jsessionid = bag['jsessionid']
cookies = {'JSESSIONID': jsessionid}
element_types = ['counters', 'valves', 'hydrants', 'analogInputs', 'digitalInputs', 'digitalOutputs', 'iris', 'rtus']
all_devices = {
    'executed_at': fields.Datetime.now(),
    'installations': {},
    'errors': []
}
try:
    url_installations = (base_url or '').rstrip('/') + '/Demeter2/v2/installations'
    installations_map = {}
    try:
        resp_inst = request_retry('GET', url_installations, cookies=cookies, timeout=timeout)
        if resp_inst.status_code == 200:
            installations_list = resp_inst.json() or []
            for inst in installations_list:
                inst_id = inst.get('installationId')
                inst_code = inst.get('code', '')
                inst_desc = inst.get('description', '')
                if inst_id:
                    # Create display name: "description (code)" or just "code" if no description
                    if inst_desc and inst_desc.strip():
                        display_name = '%s (%s)' % (inst_desc.strip(), inst_code)
                    else:
                        display_name = inst_code
                    installations_map[inst_id] = {
                        'id': inst_id,
                        'code': inst_code,
                        'description': inst_desc,
                        'display_name': display_name
                    }
        else:
            all_devices['errors'].append('Failed to get installations: HTTP %d' % resp_inst.status_code)
    except Exception as e:
        all_devices['errors'].append('Error getting installations: %s' % str(e))
    url_search = (base_url or '').rstrip('/') + '/Demeter2/v2/search'
    for element_type in element_types:
        try:
            payload = {
                'status': 'enabled',
                'types': [element_type]
            }
            resp = request_retry('POST', url_search, json=payload, cookies=cookies, timeout=timeout)
            if resp.status_code == 200:
                devices = resp.json() or []
                for device in devices:
                    installation_id = device.get('installationId')
                    device_element_type = device.get('elementType')
                    if device_element_type != element_type:
                        continue
                    if installation_id:
                        installation_key = str(installation_id)
                        if installation_key not in all_devices['installations']:
                            inst_info = installations_map.get(installation_id, {})
                            display_name = inst_info.get('display_name', 'Installation %s' % installation_id)
                            all_devices['installations'][installation_key] = {
                                'installation_id': installation_id,
                                'installation_name': display_name,
                                'devices_by_type': {}
                            }
                        if element_type not in all_devices['installations'][installation_key]['devices_by_type']:
                            all_devices['installations'][installation_key]['devices_by_type'][element_type] = []
                        all_devices['installations'][installation_key]['devices_by_type'][element_type].append(device)
            else:
                all_devices['errors'].append('Failed to get %s: HTTP %d' % (element_type, resp.status_code))
        except Exception as e:
            all_devices['errors'].append('Error getting %s: %s' % (element_type, str(e)))
except Exception as e:
    all_devices['errors'].append('General error: %s' % str(e))
bag['hidroconta_devices'] = all_devices
timestamp = fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_')
fname = 'hidroconta_devices_%s.json' % timestamp
b64 = base64.b64encode(json.dumps(all_devices, indent=2, ensure_ascii=False).encode('utf-8'))
att = env['ir.attachment'].create({
    'name': fname,
    'datas_fname': fname,
    'datas': b64,
    'mimetype': 'application/json',
    'res_model': 'remotecontrol',
    'res_id': Remote.id
})
bag['attachment_id'] = att.id
bag['attachment_name'] = fname
total_installations = len(all_devices['installations'])
total_devices = sum(len(inst.get('devices_by_type', {}).get(dt, [])) for inst in all_devices['installations'].values() for dt in element_types)
total_errors = len(all_devices.get('errors', []))
result = 'Found %d installations with %d total devices (%d errors). File: %s' % (total_installations, total_devices, total_errors, fname)

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
condition = [
    ('remotecontrol_params','!=',False),
    ('device_id.remotecontrol_id', '=', Remote.id),
    ('active', '=', True)
]
sensors = Sensor.search(condition)
sensor_plan = []
for sensor in sensors:
    device = sensor.device_id
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}
    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}
    element_id = sensor_cfg.get('element_id') or device_cfg.get('element_id')
    subtype = sensor_cfg.get('subtype') or device_cfg.get('subtype')
    subcode = sensor_cfg.get('subcode') or device_cfg.get('subcode', 0)
    start_date = sensor_cfg.get('start_date') or device_cfg.get('start_date', '2025-01-01')
    if not element_id or subtype is None:
        continue
    plan_item = {
        'odoo_sensor_id': sensor.id,
        'element_id': element_id,
        'subtype': subtype,
        'subcode': subcode,
        'start_date': start_date
    }
    sensor_plan.append(plan_item)
bag['sensor_plan'] = sensor_plan
result = 'Built sensor plan with %d sensors' % len(sensor_plan)
